MAP
    NAME "SS_MAP_AGUA_LLENADO_PIPAS"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_pipas_llenado.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_AGUA_LLENADO_PIPAS"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from pipas_llenado using unique gid using srid=32614"
        TYPE POINT
        LABELITEM "nombre"
        LABELCACHE ON
        TOLERANCE 8
        CLASS
            NAME "Puntos de llenado"
            STYLE
                SYMBOL 'puntos'
                SIZE 9
                COLOR 0 120 120
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT 'arial'
                OFFSET 0 10
                SIZE 16
                COLOR 0 120 120
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP